        def _post_trust_credential_status_receipt_sync_receipt_consume(
            self, tenant: str
        ) -> None:
            # POST /v1/trust/credential-status/receipt-sync/receipt/consume：
            # 验真并一次性消费凭证状态回执消费同步进度签名回执（持久化
            # 防重放）。
            # 1) 请求与字段约束同目录 receipt/verify：恰含 receipt（对象）、
            #    signature（非空字符串）、ndjson（字符串）、nonce
            #    （1..256 码点非空字符串）；空体、非法 JSON、非对象、
            #    键集或类型错一律 400 且仅 {"error":"请求非法"}；显式
            #    空租户头由路由统一判 400，缺省 default、按租户隔离；
            # 2) 外层合法后先按六阶段顺序验真（回执非法 -> nonce 错误
            #    -> 摘要错误 -> 锚点不可用 -> 签名格式错误 -> 签名校验
            #    失败），锚点用途为 status；失败沿用原 HTTP 200、固定
            #    reason 及优先级，响应仅含 valid、reason，不写状态、
            #    不记审计、无任何副作用；
            # 3) 验真成功后按租户以 (verifier_did, nonce) 为唯一键
            #    消费：首次 200 按键序恰返 valid、receipt_id、
            #    consumed_at（valid:true，receipt_id 为完整 receipt
            #    规范化 JSON 的 UTF-8 字节 SHA-256 小写 64 位 hex，
            #    consumed_at 为 UTC 秒精度 Z）；同键重放（receipt
            #    内容可不同）或并发后到者 200 恰返
            #    {"valid":false,"reason":"状态同步回执已消费"}，不审计；
            # 4) 首次消费与审计（trust.credential.status.sync.receipt.
            #    consumed / credential_status_sync_receipt / receipt_id）
            #    同一次原子落盘；验真失败与重放不记；落盘失败全部回滚，
            #    500 仅返 {"error":"存储失败"}，可重试；重启仍判重。
            try:
                data = self._read_json()
                if set(data) != {"receipt", "signature", "ndjson", "nonce"}:
                    raise ValidationError("请求非法")
                receipt = data["receipt"]
                signature = data["signature"]
                ndjson = data["ndjson"]
                nonce = data["nonce"]
                if not isinstance(receipt, dict):
                    raise ValidationError("请求非法")
                if not isinstance(signature, str) or not signature:
                    raise ValidationError("请求非法")
                if not isinstance(ndjson, str):
                    raise ValidationError("请求非法")
                if not isinstance(nonce, str) or not 1 <= len(nonce) <= 256:
                    raise ValidationError("请求非法")
            except (ValidationError, ValueError):
                # ValueError：JSON 内超长十进制整数触发位数上限。
                raise ValidationError("请求非法")

            reason = self._verify_presentation_sync_receipt_item(
                tenant,
                receipt,
                signature,
                ndjson,
                nonce,
                required_use="status",
            )
            if reason is not None:
                self._send_json(200, {"valid": False, "reason": reason})
                return
            receipt_id = hashlib.sha256(
                crypto.canonicalize(receipt)
            ).hexdigest()
            try:
                consumed, consumed_at = (
                    store.consume_credential_status_sync_receipt(
                        tenant,
                        receipt["verifier_did"],
                        receipt["nonce"],
                        receipt_id,
                    )
                )
            except StorageError:
                self._send_error(500, "存储失败")
                return
            if not consumed:
                self._send_json(
                    200,
                    {"valid": False, "reason": "状态同步回执已消费"},
                )
                return
            self._send_json(
                200,
                {
                    "valid": True,
                    "receipt_id": receipt_id,
                    "consumed_at": consumed_at,
                },
            )

        def _get_trust_credential_status(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}?issuer_did=...：issuer_did 须唯一
            # 且非空，否则 400；未同步（含他租户双键）404，跨租户不可
            # 探测。已同步仅返回 status、reason、updated_at。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_synced_credential_status(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                },
            )

